package com.example.starter.config;

import java.time.Clock;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 时间源配置：业务时间统一从 Clock 获取，测试可替换为可控时钟。
 */
@Configuration
public class TimeConfig {

    /**
     * 默认系统时钟（应用时区）。
     */
    @Bean
    public Clock clock() {
        return Clock.systemDefaultZone();
    }
}

package com.example.starter.domain;

/**
 * 机组行。availableKw 为最新可用出力（kW），由执行回报刷新。
 */
public record TurbineRow(long id, long farmId, String code, int capacityKw, int availableKw) {

    /**
     * 单机最低技术出力：额定容量 15% 向下取整，单位 kW。
     */
    public int minKw() {
        return capacityKw * 15 / 100;
    }
}

package com.example.starter.domain;

import java.time.LocalDateTime;

/**
 * 限电指令行。状态流转：EXECUTING → SUPERSEDED（被新指令作废）或 SEALED（日结封存，终态）。
 */
public record CommandRow(long id, long farmId, String requestId, String fingerprint, int targetKw,
                         String status, LocalDateTime issuedAt, LocalDateTime sealedAt) {

    public static final String STATUS_EXECUTING = "EXECUTING";
    public static final String STATUS_SUPERSEDED = "SUPERSEDED";
    public static final String STATUS_SEALED = "SEALED";
}

package com.example.starter.domain;

/**
 * 分摊明细行。round 为分摊轮次：1 为首次分摊，超时重分摊递增。
 */
public record AllocationRow(long id, long commandId, int round, long turbineId,
                            int availableKw, int minKw, int headroomKw, int targetKw) {
}

package com.example.starter.domain;

import java.time.LocalDateTime;

/**
 * 执行回报行。late=true 表示封存/作废后的迟到回报，仅记录事件不参与分摊。
 */
public record ReportRow(long id, long commandId, long farmId, long turbineId, String requestId,
                        String fingerprint, LocalDateTime reportTime, int actualKw, boolean late,
                        LocalDateTime receivedAt) {
}

package com.example.starter.domain;

import java.time.LocalDateTime;

/**
 * 告警/事件行。type：CURTAIL_TIMEOUT 超时未达目标；LATE_REPORT 封存后迟到回报。
 */
public record AlarmRow(long id, long commandId, Long turbineId, String type, String message,
                       LocalDateTime createdAt) {

    public static final String TYPE_CURTAIL_TIMEOUT = "CURTAIL_TIMEOUT";
    public static final String TYPE_LATE_REPORT = "LATE_REPORT";
}

package com.example.starter.web;

import org.springframework.http.HttpStatus;

/**
 * 业务异常：携带 HTTP 状态码，由全局异常处理器转为统一错误响应。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;

    public ApiException(HttpStatus status, String message) {
        super(message);
        this.status = status;
    }

    public HttpStatus status() {
        return status;
    }

    public static ApiException conflict(String message) {
        return new ApiException(HttpStatus.CONFLICT, message);
    }

    public static ApiException notFound(String message) {
        return new ApiException(HttpStatus.NOT_FOUND, message);
    }

    public static ApiException unprocessable(String message) {
        return new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, message);
    }
}

package com.example.starter.web;

import java.util.Map;

import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/**
 * 全局异常处理：业务异常按状态码返回，参数校验失败返回 400。
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(ApiException.class)
    public ResponseEntity<Map<String, Object>> handleApi(ApiException ex) {
        return ResponseEntity.status(ex.status())
                .body(Map.of("error", ex.status().name(), "message", ex.getMessage()));
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<Map<String, Object>> handleValidation(MethodArgumentNotValidException ex) {
        String message = ex.getBindingResult().getFieldErrors().stream()
                .map(e -> e.getField() + " " + e.getDefaultMessage())
                .findFirst()
                .orElse("请求参数不合法");
        return ResponseEntity.badRequest()
                .body(Map.of("error", "BAD_REQUEST", "message", message));
    }
}

package com.example.starter.util;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;

/**
 * 幂等指纹工具：对 requestId 与全部业务字段做 SHA-256。
 */
public final class Fingerprints {

    private Fingerprints() {
    }

    /**
     * 计算指纹，字段按传入顺序以竖线连接后哈希。
     */
    public static String of(String... parts) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            md.update(String.join("|", parts).getBytes(StandardCharsets.UTF_8));
            return HexFormat.of().formatHex(md.digest());
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 不可用", e);
        }
    }
}

