package com.example.starter.repo;

import java.util.List;
import java.util.Optional;

import com.example.starter.domain.TurbineRow;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/**
 * 机组数据访问。
 */
@Repository
public class TurbineRepository {

    private final JdbcTemplate jdbc;

    public TurbineRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 按风场查询机组，按 id 升序保证分摊顺序稳定。
     */
    public List<TurbineRow> findByFarmId(long farmId) {
        return jdbc.query(
                "SELECT id, farm_id, code, capacity_kw, available_kw FROM turbine WHERE farm_id = ? ORDER BY id",
                (rs, i) -> new TurbineRow(rs.getLong(1), rs.getLong(2), rs.getString(3),
                        rs.getInt(4), rs.getInt(5)),
                farmId);
    }

    public Optional<TurbineRow> findById(long id) {
        List<TurbineRow> rows = jdbc.query(
                "SELECT id, farm_id, code, capacity_kw, available_kw FROM turbine WHERE id = ?",
                (rs, i) -> new TurbineRow(rs.getLong(1), rs.getLong(2), rs.getString(3),
                        rs.getInt(4), rs.getInt(5)),
                id);
        return rows.stream().findFirst();
    }

    /**
     * 用最新出力读数刷新机组可用出力。
     */
    public void updateAvailableKw(long id, int availableKw) {
        jdbc.update("UPDATE turbine SET available_kw = ? WHERE id = ?", availableKw, id);
    }
}

package com.example.starter.repo;

import java.sql.PreparedStatement;
import java.sql.Statement;
import java.sql.Timestamp;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;

import com.example.starter.domain.CommandRow;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Repository;

/**
 * 限电指令数据访问。执行中唯一性由 active_farm_id 唯一索引保证。
 */
@Repository
public class CommandRepository {

    private static final String COLUMNS =
            "id, farm_id, request_id, fingerprint, target_kw, status, issued_at, sealed_at";

    private final JdbcTemplate jdbc;

    public CommandRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 插入执行中指令；active_farm_id 唯一索引冲突时抛出 DuplicateKeyException。
     */
    public long insertExecuting(long farmId, String requestId, String fingerprint, int targetKw,
                                LocalDateTime issuedAt) {
        KeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO curtailment_command (farm_id, request_id, fingerprint, target_kw,"
                            + " status, active_farm_id, issued_at) VALUES (?, ?, ?, ?, ?, ?, ?)",
                    Statement.RETURN_GENERATED_KEYS);
            ps.setLong(1, farmId);
            ps.setString(2, requestId);
            ps.setString(3, fingerprint);
            ps.setInt(4, targetKw);
            ps.setString(5, CommandRow.STATUS_EXECUTING);
            ps.setLong(6, farmId);
            ps.setTimestamp(7, Timestamp.valueOf(issuedAt));
            return ps;
        }, keys);
        return keys.getKey().longValue();
    }

    public Optional<CommandRow> findById(long id) {
        return queryOne("SELECT " + COLUMNS + " FROM curtailment_command WHERE id = ?", id);
    }

    public Optional<CommandRow> findByRequestId(String requestId) {
        return queryOne("SELECT " + COLUMNS + " FROM curtailment_command WHERE request_id = ?", requestId);
    }

    public Optional<CommandRow> findExecutingByFarmId(long farmId) {
        return queryOne("SELECT " + COLUMNS
                + " FROM curtailment_command WHERE farm_id = ? AND status = 'EXECUTING'", farmId);
    }

    /**
     * 作废风场当前执行中指令（同事务内与新指令生效一起提交）。
     */
    public int supersedeExecuting(long farmId) {
        return jdbc.update("UPDATE curtailment_command SET status = ?, active_farm_id = NULL"
                        + " WHERE farm_id = ? AND status = ?",
                CommandRow.STATUS_SUPERSEDED, farmId, CommandRow.STATUS_EXECUTING);
    }

    /**
     * 日结封存；仅未封存时生效，返回受影响行数。
     */
    public int seal(long id, LocalDateTime sealedAt) {
        return jdbc.update("UPDATE curtailment_command SET status = ?, sealed_at = ?,"
                        + " active_farm_id = NULL WHERE id = ? AND status <> ?",
                CommandRow.STATUS_SEALED, Timestamp.valueOf(sealedAt), id, CommandRow.STATUS_SEALED);
    }

    public int countExecutingByFarmId(long farmId) {
        Integer count = jdbc.queryForObject(
                "SELECT COUNT(*) FROM curtailment_command WHERE farm_id = ? AND status = 'EXECUTING'",
                Integer.class, farmId);
        return count == null ? 0 : count;
    }

    private Optional<CommandRow> queryOne(String sql, Object... args) {
        List<CommandRow> rows = jdbc.query(sql, (rs, i) -> new CommandRow(
                rs.getLong(1), rs.getLong(2), rs.getString(3), rs.getString(4), rs.getInt(5),
                rs.getString(6), rs.getTimestamp(7).toLocalDateTime(),
                rs.getTimestamp(8) == null ? null : rs.getTimestamp(8).toLocalDateTime()), args);
        return rows.stream().findFirst();
    }
}

package com.example.starter.repo;

import java.util.List;

import com.example.starter.domain.AllocationRow;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/**
 * 分摊明细数据访问。全部轮次保留，支持复算。
 */
@Repository
public class AllocationRepository {

    private static final String COLUMNS =
            "id, command_id, round, turbine_id, available_kw, min_kw, headroom_kw, target_kw";

    private final JdbcTemplate jdbc;

    public AllocationRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public void insert(long commandId, int round, long turbineId, int availableKw, int minKw,
                       int headroomKw, int targetKw) {
        jdbc.update("INSERT INTO command_allocation (command_id, round, turbine_id, available_kw,"
                        + " min_kw, headroom_kw, target_kw) VALUES (?, ?, ?, ?, ?, ?, ?)",
                commandId, round, turbineId, availableKw, minKw, headroomKw, targetKw);
    }

    public List<AllocationRow> findByCommandId(long commandId) {
        return jdbc.query("SELECT " + COLUMNS
                        + " FROM command_allocation WHERE command_id = ? ORDER BY round, turbine_id",
                this::map, commandId);
    }

    public List<AllocationRow> findByCommandIdAndRound(long commandId, int round) {
        return jdbc.query("SELECT " + COLUMNS
                        + " FROM command_allocation WHERE command_id = ? AND round = ? ORDER BY turbine_id",
                this::map, commandId, round);
    }

    public int maxRound(long commandId) {
        Integer round = jdbc.queryForObject(
                "SELECT COALESCE(MAX(round), 0) FROM command_allocation WHERE command_id = ?",
                Integer.class, commandId);
        return round == null ? 0 : round;
    }

    /**
     * 查询某机组最新一轮的分摊目标。
     */
    public AllocationRow findLatestForTurbine(long commandId, long turbineId) {
        return jdbc.queryForObject("SELECT " + COLUMNS
                        + " FROM command_allocation WHERE command_id = ? AND turbine_id = ?"
                        + " ORDER BY round DESC LIMIT 1",
                this::map, commandId, turbineId);
    }

    private AllocationRow map(java.sql.ResultSet rs, int i) throws java.sql.SQLException {
        return new AllocationRow(rs.getLong(1), rs.getLong(2), rs.getInt(3), rs.getLong(4),
